SQL_DOC.P_SQL:
DECLARE
V_DATE VARCHAR2(8); V_TIME VARCHAR2(8); V_COUNT_CK NUMBER; V_BUYER VARCHAR2(10) := 'KRJINR0004'; V_REVISION VARCHAR2(3) := '00';
V_IF_FLAG VARCHAR2(1) := 'N'; V_ERR_MSG VARCHAR2(300);
BEGIN
IF $LEGACY_END_YN$='Y' THEN
PROC_IF_PROGRESS_IN(V_BUYER,'RE',$QUOTATION_NO$,V_REVISION);
ELSE
SELECT COUNT(QUOTATION_SEQ), TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS') INTO V_COUNT_CK, V_DATE, V_TIME WHERE BUYER = NVL(TRIM(V_BUYER) ,' ') AND QUOTATION_NO = NVL(TRIM($QUOTATION_NO$) ,' ') AND QUOTATION_SEQ = NVL(TRIM($QUOTATION_SEQ$),' ') AND REVISION = NVL(TRIM(V_REVISION) ,' ') AND BUYER_ITEM_NO = NVL(TRIM($BUYER_ITEM_NO$), ' ');
IF V_COUNT_CK = 0 THEN
INSERT INTO IF_REDT( BUYER, QUOTATION_NO, QUOTATION_SEQ, REVISION, STATUS, ADD_DATE, BUYER_ITEM_NO, DESCRIPTION, SPECIFICATION, MAKER_NAME, ORIGIN_NAME, UNIT_MEASURE, PREV_UNIT_PRICE, REMARK, HD_REMARK, CATEG_NAME1, CATEG_NAME2, REMARK_HEAD, H_IMAGE_KEY, REMARK_DETAIL1, REMARK_DETAIL2, D_IMAGE_KEY, DWING_NO, DW_IMAGE_KEY, ADD_USER_ID, REQ_USER_NAME, REQ_USER_DEPT, REQ_USER_TEL, QC_INSPECTION, DELY_CONDITION, RD_DATE, CLOSE_DATE, ITEM_QTY, IF_FLAG, FILE_NAME, ERROR_MSG, LOAD_DATE, LOAD_TIME )VALUES ( NVL(TRIM(V_BUYER),' '), NVL(TRIM($QUOTATION_NO$),' '), NVL(TRIM($QUOTATION_SEQ$),' '), NVL(TRIM(V_REVISION),' '), NVL(TRIM($STATUS$),' '), NVL(TRIM($ADD_DATE$),' '), NVL(TRIM($BUYER_ITEM_NO$),' '), NVL(TO_SINGLE_BYTE(TRIM($DESCRIPTION$)),' '), NVL(TO_SINGLE_BYTE(TRIM($SPECIFICATION$)),' '), NVL(TRIM($MAKER_NAME$),' '), NVL(TRIM($ORIGIN_NAME$),' '), NVL(TRIM($UNIT_MEASURE$),' '), NVL( $PREV_UNIT_PRICE$ ,0), NVL(TRIM($REMARK$),' '), NVL(TRIM($HD_REMARK$),' '), NVL(TRIM($CATEG_NAME1$),' '), NVL(TRIM($CATEG_NAME2$),' '), NVL(TRIM($REMARK_HEAD$),' '), NVL(TRIM($H_IMAGE_KEY$),' '), NVL(TRIM($REMARK_DETAIL1$),' '), NVL(TRIM($REMARK_DETAIL2$),' '), NVL(TRIM($D_IMAGE_KEY$),' '), NVL(TRIM($DWING_NO$),' '), NVL(TRIM($DW_IMAGE_KEY$),' '), NVL(TRIM($ADD_USER_ID$),' '), NVL(TRIM($REQ_USER_NAME$),' '), NVL(TRIM($REQ_USER_DEPT$),' '), NVL(TRIM($REQ_USER_TEL$),' '), NVL(TRIM($QC_INSPECTION$),' '), NVL(TRIM($DELY_CONDITION$),' '), NVL(TRIM($RD_DATE$),' '), NVL(TRIM($CLOSE_DATE$),' '), NVL( $ITEM_QTY$ , 0), NVL(TRIM(V_IF_FLAG) ,' '), NVL(TRIM($FILE_NAME$),' '), NVL(TRIM(V_ERR_MSG),' '), NVL(TRIM(V_DATE),' '), NVL(TRIM(V_TIME),' '));
ELSE
UPDATE IF_REDT SET STATUS = NVL(TRIM($STATUS$) ,' '), ADD_DATE = NVL(TRIM($ADD_DATE$) ,' '), BUYER_ITEM_NO = NVL(TRIM($BUYER_ITEM_NO$) ,' '), DESCRIPTION = NVL(TO_SINGLE_BYTE(TRIM($DESCRIPTION$)) ,' '), SPECIFICATION = NVL(TO_SINGLE_BYTE(TRIM($SPECIFICATION$)) ,' '), MAKER_NAME = NVL(TRIM($MAKER_NAME$) ,' '), ORIGIN_NAME = NVL(TRIM($ORIGIN_NAME$) ,' '), UNIT_MEASURE = NVL(TRIM($UNIT_MEASURE$) ,' '), PREV_UNIT_PRICE = NVL( $PREV_UNIT_PRICE$ , 0), REMARK = NVL(TRIM($REMARK$) ,' '), HD_REMARK = NVL(TRIM($HD_REMARK$) ,' '), CATEG_NAME1 = NVL(TRIM($CATEG_NAME1$) ,' '), CATEG_NAME2 = NVL(TRIM($CATEG_NAME2$) ,' '), REMARK_HEAD = NVL(TRIM($REMARK_HEAD$) ,' '), H_IMAGE_KEY = NVL(TRIM($H_IMAGE_KEY$) ,' '), REMARK_DETAIL1 = NVL(TRIM($REMARK_DETAIL1$) ,' '), REMARK_DETAIL2 = NVL(TRIM($REMARK_DETAIL2$) ,' '), D_IMAGE_KEY = NVL(TRIM($D_IMAGE_KEY$) ,' '), DWING_NO = NVL(TRIM($DWING_NO$) ,' '), DW_IMAGE_KEY = NVL(TRIM($DW_IMAGE_KEY$) ,' '), ADD_USER_ID = NVL(TRIM($ADD_USER_ID$) ,' '), REQ_USER_NAME = NVL(TRIM($REQ_USER_NAME$) ,' '), REQ_USER_DEPT = NVL(TRIM($REQ_USER_DEPT$) ,' '), REQ_USER_TEL = NVL(TRIM($REQ_USER_TEL$) ,' '), QC_INSPECTION = NVL(TRIM($QC_INSPECTION$) ,' '), DELY_CONDITION = NVL(TRIM($DELY_CONDITION$) ,' '), RD_DATE = NVL(TRIM($RD_DATE$) ,' '), CLOSE_DATE = NVL(TRIM($CLOSE_DATE$) ,' '), ITEM_QTY = NVL( $ITEM_QTY$ , 0), IF_FLAG = NVL(TRIM(V_IF_FLAG) ,' '), FILE_NAME = NVL(TRIM($FILE_NAME$) ,' '), ERROR_MSG = NVL(TRIM(V_ERR_MSG) ,' '), LOAD_DATE = NVL(TRIM(V_DATE) ,' '), LOAD_TIME = NVL(TRIM(V_TIME) ,' ') WHERE BUYER = NVL(TRIM(V_BUYER) ,' ') AND QUOTATION_NO = NVL(TRIM($QUOTATION_NO$) ,' ') AND QUOTATION_SEQ = NVL(TRIM($QUOTATION_SEQ$),' ') AND REVISION = NVL(TRIM(V_REVISION) ,' ') AND BUYER_ITEM_NO = NVL(TRIM($BUYER_ITEM_NO$), ' ');
END IF;
END IF;
END;
